Чтобы убедиться, что область памяти отображена, вы можете использовать функцию `mmap` из ядра Linux. Функция `mmap` позволяет создать отображение файла или области памяти в адресное пространство процесса.

В вашем случае вы можете использовать функцию `mmap` для отображения области памяти по адресу 0x100000. Если область памяти не отображена, функция `mmap` вернет `-1` и установит значение `errno` на `ENOMEM` (недостаточно памяти).

Ниже приведен пример кода на C, который демонстрирует, как использовать функцию `mmap` для отображения области памяти:
```c
#include <linux/module.h>
#include <linux/mm.h>
#include <linux/slab.h>

// Функция, которая отображает область памяти
int mmap_area(void)
{
    // Адрес, по которому отображаем область памяти
    unsigned long addr = 0x100000;

    // Размер области памяти (в байтах)
    size_t size = 4096;

    // Создаем отображение области памяти
    void *ptr = mmap((void *)addr, size, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_FIXED, 0, 0);

    // Если отображение не удалось, возвращаем ошибку
    if (ptr == MAP_FAILED) {
        pr_err("Ошибка отображения области памяти: %d\n", errno);
        return -1;
    }

    // Возвращаем адрес отображения
    return 0;
}

// Инициализация модуля
int init_module(void)
{
    // Отображаем область памяти
    if (mmap_area()!= 0) {
        return -1;
    }

    // Возвращаем 0, если инициализация прошла успешно
    return 0;
}

// Удаление модуля
void cleanup_module(void)
{
    // Удаляем отображение области памяти
    munmap((void *)0x100000, 4096);
}
```
В этом примере мы используем функцию `mmap` для отображения области памяти по адресу 0x100000. Если отображение не удалось, мы выводим ошибку в журнал ядра.

